"""Bounded classical MPQS coefficients with separately checked squares."""

import random
from math import gcd, isqrt

from .. import utils
from .polynomial import MAX_COEFFICIENT_BITS, Polynomial, a_target


class CoefficientExhaustedError(Exception):
    """The finite coefficient-candidate allowance found no usable root."""


class CoefficientDivisorError(Exception):
    """Coefficient construction encountered a proper divisor of n."""

    def __init__(self, divisor):
        self.divisor = divisor


def external_square(base, half_width, *, budget, cursor=0, trials=4096):
    """Return a lifted polynomial, next cursor and coefficient certainty.

    Candidates q are 3 mod 4. A probable-prime filter is explicitly labelled;
    the construction depends on verified roots and an inverse, not that label.
    All accepted polynomials satisfy B²-N' = q²*C exactly, even if a composite
    were to pass the filter. No coefficient certainty promotes factors of n.
    """
    utils.require_integer(cursor, "coefficient cursor", 0)
    utils.require_integer(trials, "coefficient trials", 1)
    if trials > 65536 or cursor.bit_length() > MAX_COEFFICIENT_BITS // 2:
        raise ValueError(
            "external coefficient search exceeds its finite limit"
        )
    target = a_target(base.n_prime, half_width)
    start = max(3, isqrt(target), cursor)
    start += (3 - start) % 4
    for candidate in range(start, start + 4 * trials, 4):
        if 2 * candidate.bit_length() > MAX_COEFFICIENT_BITS:
            raise CoefficientExhaustedError("coefficient bit limit")
        budget.consume(
            64 * candidate.bit_length() ** 3 + base.n_prime.bit_length()
        )
        divisor = gcd(candidate, base.n)
        if utils.valid_divisor(divisor, base.n):
            raise CoefficientDivisorError(divisor)
        if gcd(candidate, base.n_prime) != 1:
            continue
        certainty = utils.classify_prime(
            candidate, rng=random.Random(candidate)
        )
        if certainty == utils.Primality.COMPOSITE:
            continue
        root = pow(base.n_prime, (candidate + 1) // 4, candidate)
        if (root * root - base.n_prime) % candidate:
            continue
        if gcd(2 * root, candidate) != 1:
            continue
        lift = (
            (base.n_prime - root * root)
            // candidate
            * utils.modular_inverse(2 * root, candidate)
        ) % candidate
        a = candidate * candidate
        b = root + candidate * lift
        polynomial = Polynomial(
            base.n, base.multiplier, a, min(b, a - b), candidate
        )
        return polynomial, candidate + 4, certainty.value
    raise CoefficientExhaustedError("coefficient candidate limit")

source.v2/benchmarks/build_phase_three_large_co:
"""Fresh independently certified balanced and adversarial P3.4 inputs."""

import argparse
import json
import random
from math import gcd, isqrt, prod
from pathlib import Path

from .. import utils
from .build_phase_two_corpus import certified_prime, verify_certificates

SEED = 31042026


def build():
    certificates, fixtures, seen = {}, [], set()
    generator = random.Random(SEED)

    def add(kind, digits, split, index, factors, **metadata):
        n = prod(factors)
        if n in seen:
            raise AssertionError("duplicate independent fixture")
        seen.add(n)
        fixtures.append(
            dict(
                id=f"{kind}_{digits}d_{split}_{index}",
                kind=kind,
                digits=len(str(n)),
                band=f"{kind}_{digits}d",
                split=split,
                n=n,
                factors=sorted(factors),
                residue8=n % 8,
                factor_digits=sorted(len(str(p)) for p in factors),
                **metadata,
            )
        )

    def pair(digits, smaller_digits=None, residue=None):
        while True:
            small_bits = (
                (digits * 3322 // 1000 + 1) // 2
                if smaller_digits is None
                else smaller_digits * 3322 // 1000 + 1
            )
            large_bits = (
                small_bits
                if smaller_digits is None
                else (digits - smaller_digits) * 3322 // 1000 + 1
            )
            p = certified_prime(small_bits, generator, certificates)
            q = certified_prime(large_bits, generator, certificates)
            n = p * q
            if smaller_digits is not None and (
                len(str(p)) != smaller_digits
                or len(str(q)) != digits - smaller_digits
            ):
                continue
            if (
                p == q
                or len(str(n)) != digits
                or (residue is not None and n % 8 != residue)
                or n in seen
            ):
                continue
            if smaller_digits is None and 100 * abs(p - q) <= min(p, q):
                continue
            return p, q

    for digits in (30, 40, 50, 60, 70, 80):
        for split, residues in (
            ("training", (1, 5)),
            ("held_out", (1, 3, 5, 7)),
        ):
            for index, residue in enumerate(residues):
                add(
                    "balanced",
                    digits,
                    split,
                    index,
                    pair(digits, residue=residue),
                    performance_representative=split == "held_out"
                    and index == 0,
                )
        print("certified balanced", digits, flush=True)
    for digits in (60, 80):
        for smaller in (5, 10, 20):
            for split, count in (("training", 1), ("held_out", 2)):
                for index in range(count):
                    add(
                        f"unbalanced_small{smaller}",
                        digits,
                        split,
                        index,
                        pair(digits, smaller_digits=smaller),
                    )
    for digits in (50, 60, 80):
        bits = (digits * 3322 // 1000 + 1) // 2
        for index in range(2):
            while True:
                p = certified_prime(bits, generator, certificates)
                proof = certificates[str(p)]
                common = proof["q"]
                found = None
                for step in range(1, 257):
                    q = p + 2 * common * step
                    if (
                        len(str(p * q)) != digits
                        or common * common <= q
                        or not utils.is_prime(q, rng=generator)
                    ):
                        continue
                    for witness in range(2, 100):
                        if (
                            pow(witness, q - 1, q) == 1
                            and gcd(pow(witness, (q - 1) // common, q) - 1, q)
                            == 1
                        ):
                            certificates[str(q)] = {
                                "kind": "pocklington",
                                "q": common,
                                "witness": witness,
                            }
                            start = isqrt(p * q)
                            start += start * start < p * q
                            distance = (p + q) // 2 - start
                            if distance <= 100000:
                                found = (q, distance)
                            break
                    if found:
                        break
                if found and p * found[0] not in seen:
                    break
            add(
                "close",
                digits,
                "held_out",
                index,
                (p, found[0]),
                fermat_iterations=found[1],
            )
            while True:
                p = certified_prime(bits, generator, certificates)
                if len(str(p * p)) == digits and p * p not in seen:
                    break
            add("square", digits, "held_out", index, (p, p))
            while True:
                p = certified_prime(
                    digits * 3322 // 1000 + 1, generator, certificates
                )
                if len(str(p)) == digits:
                    break
            add("prime", digits, "held_out", index, (p,))
    for index in range(4):
        factors = tuple(
            certified_prime(55 + index % 2, generator, certificates)
            for _ in range(3)
        )
        add("three_prime", len(str(prod(factors))), "held_out", index, factors)
    for kind, p in (("smooth_pm1", 65521), ("smooth_pp1", 65519)):
        certificates[str(p)] = {"kind": "trial"}
        for index in range(2):
            _, q = pair(60, smaller_digits=5)
            add(kind, len(str(p * q)), "held_out", index, (p, q))
    verify_certificates(certificates)
    return dict(
        schema=1,
        seed=SEED,
        seeds=[7, 29],
        fixtures=fixtures,
        certificates=certificates,
        notes=[
            (
                "All prime factors have independently checked "
                "Pocklington or exact trial proofs."
            ),
            (
                "Balanced factors are comparable in size and "
                "exclude extremely close pairs."
            ),
            (
                "Close pairs are labelled separately; their "
                "proof-generating structure is disclosed."
            ),
            "Representatives for controlled probes are preselected.",
            (
                "Factors/certificates/shape metadata are withheld "
                "from factoring methods."
            ),
        ],
    )


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--output", type=Path, required=True)
    args = parser.parse_args()
    if args.output.exists():
        parser.error("preserve existing corpus bytes")
    args.output.write_text(json.dumps(build(), indent=2) + "\n")


if __name__ == "__main__":
    main()

source.v2/benchmarks/build_phase_two_corpus.py:
"""Freeze generated inputs with independent recursive Pocklington proofs."""

import argparse
import json
import random
from math import gcd, isqrt
from pathlib import Path

from v2 import utils

GENERATION_SEED = 20261003


def certified_prime(bits, generator, certificates):
    """Generate p=k*q+1 with a certified q > sqrt(p), then prove p.

    The Factor classifier is only a candidate filter. The certificate proves
    primality independently via Pocklington's theorem; small leaves use exact
    trial division. Known factors/certificates are never given to algorithms.
    """
    if bits <= 16:
        while True:
            candidate = generator.randrange(2 ** (bits - 1), 2**bits) | 1
            if all(candidate % d for d in range(2, isqrt(candidate) + 1)):
                certificates[str(candidate)] = {"kind": "trial"}
                return candidate
    q = certified_prime(bits // 2 + 2, generator, certificates)
    lower = ((2 ** (bits - 1) - 1) // q + 2) // 2
    upper = (2**bits - 2) // (2 * q)
    while True:
        k = 2 * generator.randint(lower, upper)
        candidate = k * q + 1
        if not utils.is_prime(candidate, rng=generator):
            continue
        for witness in range(2, 100):
            if (
                pow(witness, candidate - 1, candidate) == 1
                and gcd(pow(witness, k, candidate) - 1, candidate) == 1
                and q * q > candidate
            ):
                certificates[str(candidate)] = {
                    "kind": "pocklington",
                    "q": q,
                    "witness": witness,
                }
                return candidate


def verify_certificates(certificates):
    """Verify all proof nodes without calling Factor's primality test."""
    verified = set()

    def verify(n):
        if n in verified:
            return
        proof = certificates[str(n)]
        if proof["kind"] == "trial":
            if (
                n < 2
                or n >= 2**16
                or any(n % divisor == 0 for divisor in range(2, isqrt(n) + 1))
            ):
                raise AssertionError("invalid trial certificate")
        else:
            q, witness = proof["q"], proof["witness"]
            if not 2 <= q < n or (n - 1) % q:
                raise AssertionError("invalid certificate dependency")
            verify(q)
            if not (
                q * q > n
                and pow(witness, n - 1, n) == 1
                and gcd(pow(witness, (n - 1) // q, n) - 1, n) == 1
            ):
                raise AssertionError("invalid Pocklington certificate")
        verified.add(n)

    for n in certificates:
        verify(int(n))


def build(count=40):
    """Create disjoint cohorts; large bands are capped exploration."""
    generator = random.Random(GENERATION_SEED)
    certificates = {}
    fixtures = []

    def add(band, factors, index):
        n = 1
        for prime, exponent in factors:
            n *= prime**exponent
        fixtures.append(
            {
                "id": f"{band}_{index:03d}",
                "band": band,
                "n": n,
                "factors": sorted(factors),
                "split": "training" if index < count // 2 else "held_out",
                "digits": len(str(n)),
            }
        )

    for digits in range(20, 81, 10):
        for index in range(count):
            # Choose exact decimal bands, not a float approximation to n.
            while True:
                bits = (digits * 3322 // 1000 + 1) // 2
                p = certified_prime(bits, generator, certificates)
                q = certified_prime(bits, generator, certificates)
                if p != q and len(str(p * q)) == digits:
                    break
            add(f"balanced_{digits}d", [(p, 1), (q, 1)], index)
        print("generated", digits, "digit balanced band", flush=True)
    for digits in (60, 100):
        for small_digits in (5, 10, 20, 30):
            for index in range(count):
                p = certified_prime(
                    small_digits * 3322 // 1000, generator, certificates
                )
                while True:
                    q = certified_prime(
                        (digits - small_digits) * 3322 // 1000 + 1,
                        generator,
                        certificates,
                    )
                    if len(str(p * q)) == digits:
                        break
                add(
                    f"unbalanced_{digits}d_small_{small_digits}d",
                    [(p, 1), (q, 1)],
                    index,
                )
    for index in range(count):
        p = certified_prime(24 + index % 8, generator, certificates)
        q = certified_prime(28 + index % 8, generator, certificates)
        add("powers", [(p, (2, 3, 5, 7)[index % 4])], index)
        add("random_small", [(p, 1), (q, 1)], index)
        large = certified_prime(128 + index % 16, generator, certificates)
        add("primes", [(large, 1)], index)
        # Exact small leaves make a close-factor/Fermat cohort independent.
        p = certified_prime(15, generator, certificates)
        q = p + 2
        while any(q % d == 0 for d in range(2, isqrt(q) + 1)):
            q += 2
        certificates[str(q)] = {"kind": "trial"}
        if q >= 2**16:
            continue
        add("close_small", [(p, 1), (q, 1)], index)
        # Stage-one, first/last stage-two primes, and mixed saturation cases.
        smooth = (13, 19, 31, 61, 211, 607)[index % 6]
        other = (1019, 1009, 1013)[index % 3]
        for value in (smooth, other):
            certificates[str(value)] = {"kind": "trial"}
        add("pm1_boundaries", [(smooth, 1), (other, 1)], index)
        plus = (11, 23, 59, 107, 179)[index % 5]
        certificates[str(plus)] = {"kind": "trial"}
        add("pp1_boundaries", [(plus, 1), (other, 1)], index)
    for index, factors in enumerate(
        (
            [(151, 1), (751, 1), (28351, 1)],
            [(10670053, 1), (32010157, 1)],
        )
    ):
        # Independent exact trial proofs suffice for these published fixtures.
        for prime, _ in factors:
            if prime >= 2**16:
                continue
            certificates[str(prime)] = {"kind": "trial"}
        n = 1
        for prime, exponent in factors:
            n *= prime**exponent
        fixtures.append(
            {
                "id": f"pseudoprime_{index}",
                "band": "pseudoprimes",
                "n": n,
                "factors": factors,
                "split": "held_out",
                "digits": len(str(n)),
            }
        )
    verify_certificates(certificates)
    return {
        "schema": 1,
        "generation_seed": GENERATION_SEED,
        "inputs_per_main_band": count,
        "certificates": certificates,
        "seeds": [104729, 130363, 155921, 181081, 206369],
        "fixtures": fixtures,
        "notes": [
            "Balanced 20-80 digit bands are capped exploration until measured",
            "No p+1 engine yet; p+1 fixtures measure portfolio coverage",
            "Verify larger pseudoprime factors by independent trial division",
            "Training and held-out fixture IDs are disjoint",
        ],
    }


def main():
    """Generate once; refuse to replace a frozen corpus accidentally."""
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--output", type=Path, required=True)
    parser.add_argument("--count", type=int, default=40)
    args = parser.parse_args()
    if args.output.exists():
        parser.error("output exists; select a new corpus filename")
    if args.count < 40 or args.count % 2:
        parser.error("use at least 40 inputs per band and equal splits")
    args.output.write_text(json.dumps(build(args.count), indent=2) + "\n")


if __name__ == "__main__":
    main()

source.v2/benchmarks/build_phase_three_parallel:
"""Build independent certified P3.6 training and held-out workloads."""

import argparse
import json
import random
import sys
from math import isqrt
from pathlib import Path

from .. import utils

OUTPUT = Path(__file__).with_name("phase_three_p36_corpus.json")


def build():
    generator = random.Random(36042026)
    fixtures = []
    for band, low, high in (
        ("small", 4000, 8000),
        ("medium", 1_000_000, 4_000_000),
    ):
        for split, count in (("training", 4), ("held_out", 4)):
            for index in range(count):
                primes = []
                while len(primes) < 2:
                    value = generator.randrange(low, high) | 1
                    while (
                        utils.classify_prime(value) != utils.Primality.PROVEN
                    ):
                        value += 2
                    if value not in primes:
                        primes.append(value)
                primes.sort()
                for prime in primes:
                    if any(
                        prime % divisor == 0
                        for divisor in range(2, isqrt(prime) + 1)
                    ):
                        raise AssertionError(
                            "independent prime certification failed"
                        )
                fixtures.append(
                    dict(
                        id=f"{band}_{split}_{index}",
                        band=band,
                        split=split,
                        n=primes[0] * primes[1],
                        factors=primes,
                    )
                )
    return dict(schema=1, seed=36042026, fixtures=fixtures)


def main():
    if sys.implementation.name != "pypy" or sys.version_info[:2] != (3, 11):
        raise RuntimeError("use PyPy Python 3.11")
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--output", type=Path, default=OUTPUT)
    args = parser.parse_args()
    args.output.write_text(json.dumps(build(), indent=2) + "\n")


if __name__ == "__main__":
    main()

